function Get-NonMetadataHashes($base) {
  $map = @{}
  Get-ChildItem -File -Recurse $base | Where-Object { $_.FullName -notmatch '\\.mcs(\\|$)' } | ForEach-Object {
    $rel = $_.FullName.Substring($base.Length + 1)
    $map[$rel] = (Get-FileHash $_.FullName -Algorithm SHA256).Hash
  }
  return $map
}
